  const modName=id=> id===OTHER ? 'Everything else' : ((modById.get(id)||{}).name || id);

  
  const bucket=new Map();
  const B=id=>{ if(!bucket.has(id)) bucket.set(id,{ents:[],screens:0,actions:0,desc:''}); return bucket.get(id); };
